import math
from decimal import Decimal, getcontext

getcontext().prec = 50

def reference_attention(scores, values, valid, dv):
    if not scores:
        return []
    out = []
    for i, row in enumerate(scores):
        chosen = [j for j in range(len(row)) if valid[i][j]]
        if not chosen:
            out.append([0.0] * dv)
            continue
        mx = max(row[j] for j in chosen)
        den = Decimal(0)
        num = [Decimal(0) for _ in range(dv)]
        for j in chosen:
            w = (Decimal(row[j]) - Decimal(mx)).exp()
            den += w
            for k in range(dv):
                num[k] += w * Decimal(values[j][k])
        out.append([float(num[k] / den) for k in range(dv)])
    return out

def tiled_attention(scores, values, valid, Bq, Bk, faulty=None):
    L = len(scores)
    if L == 0:
        return []
    S = len(scores[0])
    dv = len(values[0]) if values else 0
    out = [[0.0] * dv for _ in range(L)]
    for q0 in range(0, L, Bq):
        for q in range(q0, min(q0 + Bq, L)):
            m = -math.inf
            l = 0.0
            u = [0.0] * dv
            for k0 in range(0, S, Bk):
                zs = []
                for j in range(k0, min(k0 + Bk, S)):
                    if faulty == 'include_padding':
                        ok = True
                    else:
                        ok = valid[q][j]
                    if ok:
                        zs.append((j, scores[q][j]))
                if not zs:
                    continue
                mt = max(s for _, s in zs)
                if l == 0.0:
                    mn = mt
                    alpha = 0.0
                else:
                    mn = max(m, mt)
                    if faulty == 'no_rescale':
                        alpha = 1.0
                    else:
                        alpha = math.exp(m - mn)
                ws = [math.exp(s - mn) for _, s in zs]
                l = alpha * l + math.fsum(ws)
                for k in range(dv):
                    u[k] = alpha * u[k] + math.fsum(ws[t] * values[zs[t][0]][k] for t in range(len(zs)))
                m = mn
            if l > 0.0:
                out[q] = [x / l for x in u]
            else:
                out[q] = [0.0] * dv
    return out

def max_abs_diff(a, b):
    if len(a) != len(b):
        return math.inf
    best = 0.0
    for ra, rb in zip(a, b):
        if len(ra) != len(rb):
            return math.inf
        for x, y in zip(ra, rb):
            best = max(best, abs(x - y))
    return best

def run_case(name, scores, values, valid, Bq, Bk, dv):
    ref = reference_attention(scores, values, valid, dv)
    got = tiled_attention(scores, values, valid, Bq, Bk)
    diff = max_abs_diff(ref, got)
    print('correct ' + name + ': max_abs_diff=' + format(diff, '.3e'))
    if diff > 1e-9:
        raise AssertionError('independent reference mismatch: ' + name)
    return ref

def expect_fault(name, scores, values, valid, Bq, Bk, dv, faulty, threshold):
    ref = reference_attention(scores, values, valid, dv)
    got = tiled_attention(scores, values, valid, Bq, Bk, faulty=faulty)
    diff = max_abs_diff(ref, got)
    print('negative ' + name + ': max_abs_diff=' + format(diff, '.3e'))
    if diff <= threshold:
        raise AssertionError('negative control was not detected: ' + name)
    return diff

def main():
    print('K-HW-008 CPU attention tile check; not a Neuron or GPU measurement')

    causal_scores = [[((i + 1) * (j + 2)) % 7 - 3 for j in range(5)] for i in range(5)]
    causal_values = [[(j + 1) % 3, (j + 2) % 3] for j in range(5)]
    causal_valid = [[j <= i for j in range(5)] for i in range(5)]
    run_case('causal_5x5', causal_scores, causal_values, causal_valid, 2, 2, 2)

    pad_scores = [[1, 2, 3, 20, 21] for _ in range(3)]
    pad_values = [[1, 0], [0, 1], [1, 1], [100, -100], [-100, 100]]
    pad_valid = [[j < 3 for j in range(5)] for _ in range(3)]
    run_case('padding_mask', pad_scores, pad_values, pad_valid, 2, 2, 2)
    expect_fault('include_padding', pad_scores, pad_values, pad_valid, 2, 2, 2, 'include_padding', 1e-6)

    rescale_scores = [[0, 10]]
    rescale_values = [[1, 0], [0, 1]]
    rescale_valid = [[True, True]]
    run_case('rescale_two_blocks', rescale_scores, rescale_values, rescale_valid, 1, 1, 2)
    expect_fault('no_rescale', rescale_scores, rescale_values, rescale_valid, 1, 1, 2, 'no_rescale', 1e-6)

    empty = run_case('empty_L0', [], [], [], 2, 2, 2)
    if empty != []:
        raise AssertionError('empty input should produce empty output')

    masked_scores = [[0, 0], [1, 2]]
    masked_values = [[1], [2]]
    masked_valid = [[False, False], [True, True]]
    ref = run_case('all_masked_row', masked_scores, masked_values, masked_valid, 1, 1, 1)
    if ref[0] != [0.0]:
        raise AssertionError('all-masked row should be zero by the declared contract')
    print('edge all_masked_row output=' + str(ref))

    print('observations: dense reference, online merge, mask, empty input, and two injected faults were checked')

if __name__ == '__main__':
    main()
